#include "99_Default/pch.h"
#include "IceProjectile.h"
#include "../Component/Transform/Transform.h"
#include "../Component/Sprite/SpriteRenderer.h"
#include "../Component/Collider/BoxCollider.h"
#include "../../01_Manager/ResourceManager/ResourceManager.h"
#include "../../01_Manager/ObjectManager/ObjectManager.h"
#include "../../01_Manager/RenderManager/RenderManager.h"
#include "../Entity/Player/Player.h"

IceProjectile::IceProjectile(float x, float y)
    : GameObject(GOID_NONE, L"", L"", false),
    m_speed(400.0f), m_maxDistance(600.0f), m_traveledDistance(0.0f), m_damage(10), m_fireDir(DIR_DOWN)
{
    m_type = GO_TYPE_NONE;
}

IceProjectile::~IceProjectile() {}

void IceProjectile::Init()
{
    GameObject::Init();

    m_renderer = AddComponent<SpriteRenderer>(LAYER_WORLD_OBJECT);
}

void IceProjectile::Update(float deltaTime)
{
    if (!IsEnabled()) return;

    GameObject::Update(deltaTime);

    Transform* trans = GetComponent<Transform>();
    if (!trans) return;

    float dx = 0, dy = 0;
    switch (m_fireDir)
    {
    case DIR_UP: dy = -1; break;
    case DIR_DOWN: dy = 1; break;
    case DIR_LEFT: dx = -1; break;
    case DIR_RIGHT: dx = 1; break;
    }

    float moveDist = m_speed * deltaTime;
    trans->SetPosition(trans->GetX() + dx * moveDist, trans->GetY() + dy * moveDist);
    m_traveledDistance += moveDist;

    if (m_traveledDistance >= m_maxDistance)
    {
        SetActive(false);
        return;
    }

    // 플레이어 충돌 체크
    Player* player = dynamic_cast<Player*>(ObjectManager::GetInstance()->GetPlayer());
    if (player && player->IsEnabled())
    {
        BoxCollider* playerCollider = player->GetComponent<BoxCollider>();
        if (m_collider && playerCollider && m_collider->IntersectsCollider(playerCollider))
        {
            player->Damaged(m_damage);
            player->SetSlow(3.0f, 0.5f); // 3초간 50% 감속
            SetActive(false);
        }
    }
}

void IceProjectile::Render()
{
    // SpriteRenderer가 알아서 처리함. 
    // 하지만 수동으로 렌더링 호출이 필요한 구조인지 확인 필요.
    // 보통 RenderManager에서 관리함.
}

void IceProjectile::Fire(float x, float y, Direction dir, int damage, float speed, float maxDistance)
{
    Transform* trans = GetComponent<Transform>();
    if (trans)
    {
        trans->SetPosition(x, y);
    }
    m_fireDir = dir;
    m_damage = damage;
    m_speed = speed;
    m_maxDistance = maxDistance;
    m_traveledDistance = 0.0f;

    // Sprite 설정 (이미 Boss_IceHound에서 로드했을 것)
    if (m_renderer && !m_renderer->GetSprite())
    {
        auto sprite = ResourceManager::GetInstance()->GetSprite(L"IceHound_ice_ProjectTile.png");
        if (sprite)
        {
            m_renderer->SetSprite(sprite);

            // 콜라이더 설정 (이미지가 있을 때 크기 맞춰서)
            if (!m_collider)
            {
                m_collider = AddComponent<BoxCollider>();
                m_collider->SetObjectCollider(-20, -20, 40, 40);
            }
        }
    }

    SetActive(true);
}

#include "99_Default/pch.h"
#include "IceProjectile.h"
#include "../Component/Transform/Transform.h"
#include "../Component/Sprite/SpriteRenderer.h"
#include "../Component/Collider/CircleCollider.h"
#include "../../01_Manager/ResourceManager/ResourceManager.h"
#include "../../01_Manager/ObjectManager/ObjectManager.h"
#include "../../01_Manager/RenderManager/RenderManager.h"
#include "../Entity/Player/Player.h"

IceProjectile::IceProjectile(float x, float y)
    : Projectile(GOID_NONE, L"", L"", false)
{
    // 기본값 세팅은 Projectile에서 처리
}

IceProjectile::~IceProjectile() {}

void IceProjectile::Init()
{
    Projectile::Init();
    m_renderer = AddComponent<SpriteRenderer>(LAYER_WORLD_OBJECT);
    if (!m_collider) {
        m_collider = AddComponent<CircleCollider>();
        static_cast<CircleCollider*>(m_collider)->SetObjectCollider(0, 0, 20.0f); // 반지름 20 예시
    }
}

void IceProjectile::Update(float deltaTime)
{
    Projectile::Update(deltaTime);
}

void IceProjectile::Render()
{
    // SpriteRenderer가 알아서 처리함
}

void IceProjectile::Fire(float x, float y, Direction dir, int damage, float speed, float maxDistance)
{
    Projectile::Fire(x, y, dir, damage, speed, maxDistance);
    // Sprite 설정
    if (m_renderer && !m_renderer->GetSprite())
    {
        auto sprite = ResourceManager::GetInstance()->GetSprite(L"IceHound_ice_ProjectTile.png");
        if (sprite)
        {
            m_renderer->SetSprite(sprite);
        }
    }
    SetActive(true);
}

void IceProjectile::OnHit(GameObject* target)
{
    Player* player = dynamic_cast<Player*>(target);
    if (player)
    {
        player->Damaged(m_damage);
        player->SetSlow(3.0f, 0.5f); // 3초간 50% 감속
    }
    SetActive(false);
}
